// The mixtape draws from Saad's two hand-picked Spotify playlists.
// The song list lives in playlist.json, generated by `npm run sync-playlist`
// (re-run it whenever the playlists change). Songs play from YouTube.
import PLAYLISTS from './playlist.json'

export const MODES = [
  { id: 'international', label: 'International' },
  { id: 'local', label: 'Local' },
]

const CRATE_SIZE = 5
const COLORS = ['#E01B7A', '#0FA3A3', '#FFC42E', '#5C94FC', '#C84C0C', '#2BB24C', '#7A2E8C', '#D98C7A', '#AE1260']

function shuffle(list) {
  const a = [...list]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

// Deal a fresh crate of random songs, avoiding the ones just shown when possible.
export function dealCrate(mode, previous = []) {
  const all = PLAYLISTS[mode]?.tracks || []
  const fresh = all.filter((t) => !previous.includes(t.youtubeId))
  const pool = fresh.length >= CRATE_SIZE ? fresh : all
  return shuffle(pool)
    .slice(0, CRATE_SIZE)
    .map((t, i) => ({ title: t.title, artist: t.artist, youtubeId: t.youtubeId, color: COLORS[i % COLORS.length] }))
}
